D=Path(__file__).parent
queue=json.loads((D/'queue-1.json').read_text())['people']
old={p['person_id']:p for p in json.loads(Path('data/people-wikidata.json').read_text())['people']}
rows={}
def source(url,title,locator,support,access='Search-returned page text inspected; only the stated biographical scope checked.'):
 return dict(url=url,title=title,locator=locator,support=support,checked_on='2026-10-25',check_scope=access)
def add(pid,status,identity,sources,year=None,date=None,birth=None,limits=''):
 prev=old.get(pid,{})
 life=prev.get('life') or {}
 qid=(prev.get('wikidata') or {}).get('qid')
 r=dict(person_id=pid,status=status,death_year=year,death_date=date,death_precision='day' if date else 'year' if year else None,checked_on='2026-10-25',identity_rationale=identity,sources=sources,previous_death_data=dict(sheet='data/people-wikidata.json',record_present=bool(prev),qid=qid,death=life.get('death'),death_precision=life.get('death_precision'),retrieved=life.get('retrieved'),source=life.get('source')),confidence='high' if status=='deceased' else 'moderate_to_high',limits=limits or ('Status is supported by positive recent institutional/author evidence. This is a dated check, not proof against an unreported death after that evidence.' if status=='living' else 'Death year checked. No career, work, field or influence interval is inferred from the lifespan.'))
 if birth:r['birth_year']=birth
 if life.get('death') and not date and pid not in ['ernest_labrousse','lucien_febvre']:
  r['retained_prior_precise_death']={'date':life['death'],'precision':life.get('death_precision'),'source_url':'https://www.wikidata.org/wiki/'+qid+'#P570','previous_checked_on':life.get('retrieved'),'scope':'Prior date-sheet statement; current institutional source corroborates death year, not necessarily the day.'}
 rows[pid]=r
